/**
 * Prepaid mobile recharge: operators, circles and tariff books.
 *
 * **The operators are the four real Indian networks, and the plans are not.**
 * Every price, allowance and validity below is generated by this project -- none
 * of it is any network's published tariff, and none of it should be read as one.
 * The recharge page says so above the plan sheet rather than in small print,
 * because a page that takes money against a price needs to be clear about where
 * that price came from.
 *
 * Nothing here reproduces a network's logo either: the marks in
 * `components/pay/operator-mark.tsx` are original geometry, and the colours are
 * there to tell four chips apart in a row rather than to stand in for a brand.
 *
 * **The telecom circles are real.** India's prepaid market genuinely is divided
 * into the twenty-two licensed service areas listed here, and tariffs really
 * are priced per circle. That part is public fact and worth being right about.
 *
 * **The plans are generated, not typed out.** Forty per operator, composed from
 * each operator's own price ladder and benefit pool by a seeded PRNG -- the
 * same technique `data/catalog.ts` uses for the product catalogue, for the same
 * reason: 160 hand-written entries would drift, and a deterministic generator
 * gives every machine the same book.
 */

export interface OperatorTariff {
  /** Daily-data packs: the spine of any Indian prepaid sheet. */
  dailyData: string[];
  /** 28-day price points. Longer packs are derived from these. */
  basePrices: number[];
  /** Extras this operator bundles, drawn from deterministically. */
  perks: string[];
  /** Data-only top-up sizes. */
  topUpData: string[];
}

export interface Operator {
  id: string;
  name: string;
  short: string;
  /** Tailwind classes for the operator chip. */
  tone: string;
  /** Brand colour for the generated mark. */
  colour: string;
  tagline: string;
  tariff: OperatorTariff;
}

