export const PLAN_TABS = [
  'Popular',
  'Unlimited 5G',
  'Data',
  'Entertainment',
  'Gaming',
  'Top-up',
] as const;

export type PlanTab = (typeof PLAN_TABS)[number];

export interface RechargePlan {
  id: string;
  operatorId: string;
  /** Rupees. Converted to paise at the edge, like the rest of the catalogue. */
  rupees: number;
  data: string;
  /** Days, or null for a pack that rides on the existing validity. */
  validityDays: number | null;
  validity: string;
  calls: string;
  sms: string;
  benefits: string[];
  tabs: PlanTab[];
}

// ---------------------------------------------------------------- generation

/** FNV-1a, matching the rest of the project's deterministic generators. */
function hash(value: string): number {
  let h = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    h ^= value.charCodeAt(index);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** mulberry32 -- small, fast, seedable. No `Math.random()` anywhere. */
function makeRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function pick<T>(items: readonly T[], random: () => number): T {
  const item = items[Math.floor(random() * items.length) % items.length];
  if (item === undefined) throw new Error('pick: empty list');
  return item;
}

/** Longer packs cost less per day, which is the whole point of buying one. */
const TERMS: Array<{ days: number; label: string; multiplier: number }> = [
  { days: 28, label: '28 days', multiplier: 1 },
  { days: 56, label: '56 days', multiplier: 1.85 },
  { days: 84, label: '84 days', multiplier: 2.6 },
  { days: 365, label: '365 days', multiplier: 9.5 },
];

const PLANS_PER_OPERATOR = 40;

/**
 * One operator's book of forty.
 *
 * The mix mirrors a real prepaid sheet: unlimited packs across four terms, then
 * data top-ups that do not extend validity, entertainment and gaming add-ons,
 * and plain talktime. Prices are rounded to a rupee and made unique within the
 * operator, because two plans at the same price in the same list is the kind of
 * thing that reads as filler.
 */
function generatePlans(operator: Operator): RechargePlan[] {
  const random = makeRandom(hash(`recharge:${operator.id}`));
  const { dailyData, basePrices, perks, topUpData } = operator.tariff;
  const plans: RechargePlan[] = [];
  const takenPrices = new Set<number>();

  const priceFor = (base: number, multiplier: number): number => {
    let rupees = Math.round(base * multiplier);
    // Nudge upward until unique: a duplicate price with different contents is
    // indistinguishable to a shopper scanning a column of amounts.
    while (takenPrices.has(rupees)) rupees += 1;
    takenPrices.add(rupees);
    return rupees;
  };

  const add = (plan: Omit<RechargePlan, 'id' | 'operatorId'>): void => {
    plans.push({ ...plan, id: `${operator.id}-${plans.length + 1}`, operatorId: operator.id });
  };

  // ---- unlimited packs: every daily allowance across every term ----------
  for (const term of TERMS) {
    for (const data of dailyData) {
      if (plans.length >= 28) break;
      const base = pick(basePrices, random);
      const benefits = [perks[0] ?? 'Unlimited 5G'];
      if (random() > 0.55) benefits.push(pick(perks.slice(1), random));

      const tabs: PlanTab[] = ['Unlimited 5G'];
      if (term.days <= 56) tabs.push('Popular');
      if (benefits.some((benefit) => benefit.includes('Prime Video'))) tabs.push('Entertainment');
      if (benefits.some((benefit) => benefit.includes('Gaming'))) tabs.push('Gaming');

      add({
        rupees: priceFor(base, term.multiplier),
        data,
        validityDays: term.days,
        validity: term.label,
        calls: 'Unlimited',
        sms: '100/day',
        benefits,
        tabs,
      });
    }
  }

  // ---- data top-ups: no validity of their own ----------------------------
  for (const data of topUpData) {
    add({
      rupees: priceFor(19 + Math.floor(random() * 180), 1),
      data,
      validityDays: null,
      validity: 'Existing plan',
      calls: 'NA',
      sms: 'NA',
      benefits: ['Rides on your current validity'],
      tabs: ['Data', 'Top-up'],
    });
  }

  // ---- data packs with their own validity --------------------------------
  for (const days of [7, 30, 56]) {
    add({
      rupees: priceFor(49 + Math.floor(random() * 200), 1),
      data: pick(topUpData, random),
      validityDays: days,
      validity: `${days} days`,
      calls: 'NA',
      sms: 'NA',
      benefits: [],
      tabs: ['Data'],
    });
  }

  // ---- entertainment and gaming add-ons ----------------------------------
  add({
    rupees: priceFor(55 + Math.floor(random() * 140), 1),
    data: pick(topUpData, random),
    validityDays: 28,
    validity: '28 days',
    calls: 'NA',
    sms: 'NA',
    benefits: ['Prime Video included'],
    tabs: ['Entertainment'],
  });
  add({
    rupees: priceFor(99 + Math.floor(random() * 160), 1),
    data: pick(topUpData, random),
    validityDays: 30,
    validity: '30 days',
    calls: 'NA',
    sms: 'NA',
    benefits: ['Live TV pack'],
    tabs: ['Entertainment', 'Top-up'],
  });
  add({
    rupees: priceFor(111 + Math.floor(random() * 120), 1),
    data: pick(topUpData, random),
    validityDays: 28,
    validity: '28 days',
    calls: 'NA',
    sms: 'NA',
    benefits: ['Gaming pass'],
    tabs: ['Gaming'],
  });
  add({
    rupees: priceFor(399 + Math.floor(random() * 200), 1),
    data: pick(dailyData, random),
    validityDays: 28,
    validity: '28 days',
    calls: 'Unlimited',
    sms: '100/day',
    benefits: ['Gaming pass', 'Unlimited 5G'],
    tabs: ['Gaming', 'Unlimited 5G'],
  });

  // ---- plain talktime ----------------------------------------------------
  for (const amount of [10, 20, 50, 100]) {
    if (plans.length >= PLANS_PER_OPERATOR) break;
    add({
      rupees: priceFor(amount, 1),
      data: 'NA',
      validityDays: null,
      validity: 'Existing plan',
      calls: `₹${(amount * 0.8175).toFixed(2)} talktime`,
      sms: 'NA',
      benefits: [],
      tabs: ['Top-up'],
    });
  }

  // The ladders above are sized to overshoot; trim to exactly forty so every
  // operator's sheet is the same depth.
  while (plans.length < PLANS_PER_OPERATOR) {
    const data = pick(dailyData, random);
    add({
      rupees: priceFor(pick(basePrices, random), 1.4),
      data,
      validityDays: 28,
      validity: '28 days',
      calls: 'Unlimited',
      sms: '100/day',
      benefits: [perks[0] ?? 'Unlimited 5G'],
      tabs: ['Unlimited 5G', 'Popular'],
    });
  }

  return plans.slice(0, PLANS_PER_OPERATOR);
}

/** Every operator's book, keyed by operator id. */
export const PLANS_BY_OPERATOR: Readonly<Record<string, RechargePlan[]>> = Object.fromEntries(
  OPERATORS.map((operator) => [operator.id, generatePlans(operator)]),
);

/** Flat list, for the places that do not care whose plan it is. */
export const RECHARGE_PLANS: readonly RechargePlan[] = OPERATORS.flatMap(
  (operator) => PLANS_BY_OPERATOR[operator.id] ?? [],
);

const PLANS_BY_ID = new Map(RECHARGE_PLANS.map((plan) => [plan.id, plan]));
const OPERATORS_BY_ID = new Map(OPERATORS.map((operator) => [operator.id, operator]));

export function findPlan(id: string): RechargePlan | undefined {
  return PLANS_BY_ID.get(id);
}

export function findOperator(id: string): Operator | undefined {
  return OPERATORS_BY_ID.get(id);
}

export function plansFor(operatorId: string): RechargePlan[] {
  return PLANS_BY_OPERATOR[operatorId] ?? [];
}

export function plansForTab(operatorId: string, tab: PlanTab): RechargePlan[] {
  return plansFor(operatorId)
    .filter((plan) => plan.tabs.includes(tab))
    .sort((a, b) => a.rupees - b.rupees);
}
